ALTER TABLE comments ADD COLUMN parent TEXT REFERENCES comments(id) ON DELETE CASCADE;
ALTER TABLE comments ADD COLUMN owner TEXT;
ALTER TABLE comments ADD COLUMN deleted INTEGER NOT NULL DEFAULT 0 CHECK(deleted IN (0,1));
UPDATE comments SET owner=(SELECT id FROM local_users WHERE username=comments.author);
CREATE INDEX comments_thread ON comments(post,parent,created);
CREATE INDEX comments_parent ON comments(parent);
CREATE TABLE comment_likes(user TEXT NOT NULL,comment TEXT NOT NULL REFERENCES comments(id) ON DELETE CASCADE,PRIMARY KEY(user,comment));
CREATE INDEX comment_likes_comment ON comment_likes(comment);

ALTER TABLE local_users ADD COLUMN role TEXT NOT NULL DEFAULT 'member' CHECK(role IN ('member','moderator'));
ALTER TABLE local_users ADD COLUMN banned INTEGER NOT NULL DEFAULT 0 CHECK(banned IN (0,1));
ALTER TABLE local_users ADD COLUMN ban_reason TEXT NOT NULL DEFAULT '';
CREATE TABLE post_controls(post TEXT PRIMARY KEY,removed INTEGER NOT NULL DEFAULT 0,locked INTEGER NOT NULL DEFAULT 0,pinned INTEGER);
CREATE TABLE moderation_log(id TEXT PRIMARY KEY,moderator TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL,reason TEXT NOT NULL DEFAULT '',created INTEGER NOT NULL);
CREATE INDEX moderation_log_created ON moderation_log(created);
